        let sentinel = Inputs.sentinel(H.Lane.self, count: 4 * H.laneCount)
        for (a, b, c) in mixedTriples(aInputs, bInputs, cInputs, seed: 0xABF8_61FD_7B04_B124) {
            let portLanes = unsafe withGuardedLanes(sentinel) { destination in
                unsafe portStoreInterleaved4F64ConstantD(a, b, c, to: destination)
            }.lanes
            let referenceLanes = unsafe withGuardedLanes(sentinel) { destination in
                unsafe highwayStoreInterleaved4F64ConstantD(a, b, c, to: destination)
            }.lanes
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c))"
            )
        }
        mismatches.record()
    }

